mapper.select:
select count(1)
from review_cards card
inner join user_error_types user_error_type
    on user_error_type.id = card.user_error_type_id
   and user_error_type.status = 'ACTIVE'
where card.user_id = #{userId}
  and card.deleted = false
  and card.status = #{status}
  and user_error_type.learning_mode = #{learningMode}

    and card.due_at <= #{now}

select card.id, card.user_error_type_id, user_error_type.error_type_id, error_type.code as error_type_code, case when user_error_type.learning_mode = 'EN_TO_JA' then error_type.name_en else error_type.name end as error_type_name, user_error_type.name as user_error_type_name, user_error_type.description as user_error_type_description, card.status, card.due_at, cycle.cycle_no, coalesce(cycle.successful_review_count, 0) as successful_review_count, coalesce(cycle.failed_review_count, 0) as failed_review_count, coalesce(cycle.target_success_count, 0) as target_success_count, coalesce(progress.original_question_count, 0) as original_question_count, coalesce(progress.original_passed_count, 0) as original_passed_count, coalesce(progress.retry_question_count, 0) as retry_question_count, coalesce(progress.pending_question_count, 0) as pending_question_count, card.last_reviewed_at, card.mastered_at from review_cards card inner join user_error_types user_error_type on user_error_type.id = card.user_error_type_id inner join error_types error_type on error_type.id = user_error_type.error_type_id left join lateral ( select * from review_cycles where review_card_id = card.id order by cycle_no desc limit 1 ) cycle on true left join lateral ( select count(*) filter (where question_role = 'ORIGINAL')::integer as original_question_count, count(*) filter (where question_role = 'ORIGINAL' and review_status = 'PASSED')::integer as original_passed_count, count(*) filter (where review_status = 'RETRY')::integer as retry_question_count, count(*) filter (where review_status = 'PENDING')::integer as pending_question_count from review_cycle_questions where review_cycle_id = cycle.id ) progress on true where card.user_id = #{userId} and card.deleted = false and user_error_type.status = 'ACTIVE' and card.status = #{status} and user_error_type.learning_mode = #{learningMode}
and card.due_at <= #{now}
order by card.due_at asc nulls last, card.updated_at desc, card.id desc limit #{limit} offset #{offset}

mapper.insert:
insert into review_cards (
    user_id, user_error_type_id, status, ease_factor, repetition_count, interval_days,
    lapse_count, due_at, last_reviewed_at, mastered_at, deleted, created_at, updated_at
) values (
    #{userId}, #{userErrorTypeId}, #{status}, #{easeFactor}, #{repetitionCount}, #{intervalDays},
    #{lapseCount}, #{dueAt}, #{lastReviewedAt}, #{masteredAt}, #{deleted}, #{createdAt}, #{updatedAt}
)
on conflict (user_error_type_id) do nothing

mapper.update:
update review_cards
set deleted = true,
    updated_at = #{updatedAt}
where id = #{id}
  and user_id = #{userId}
  and deleted = false
